const cds = require('../../../cds')
const { path } = cds.utils
const { readProject } = require('../../projectReader')
const { merge } = require('../../merge')
const { srv4, portal, portalDeployer, xsuaa, ias, html5RepoHost, appDeployer, approuter, mtxSidecar4 } = require('../../registries/mta')
const { renderAndCopy } = require('../../template')
const KymaTemplate = require('../kyma')

module.exports = class PortalTemplate extends require('../../plugin') {

  static help() {
    return 'SAP BTP Portal Service'
  }

  requires() {
    return ['html5-repo', 'approuter']
  }

  static hasInProduction(env) {
    return !!env.requires?.portal
  }

  async run() {
    const project = readProject()
    const { configFile } = project
    await merge(__dirname, 'files/package.json.hbs').into(configFile, { project })
    await renderAndCopy(path.join(__dirname, 'files/portal-site'), 'app/portal/portal-site', project)
  }

  async combine(facet) {
    const project = readProject(facet)
    const { isJava, affected, srv, apps } = project

    if (affected('multitenancy')) {
      await merge(__dirname, 'files/package.sidecar.json').into('mtx/sidecar/package.json')
    }

    if (affected('mta', 'xsuaa', 'ias', 'html5-repo', 'approuter', 'multitenancy', 'sample')) {
      const srvModule = srv4(srv.path)
      const hasApps = apps.length > 0
      project.withApps = hasApps
      const additions = [srvModule, portal, ...(hasApps ? [appDeployer] : []), portalDeployer]
      const relationships = [{
        insert: [portal, 'name'],
        into: [portalDeployer, 'requires', 'name']
      }]
      if (hasApps && affected('mta', 'sample')) {
        relationships.push({
          insert: [appDeployer, 'name'],
          into: [portalDeployer, 'requires', 'name']
        })
      }

      if (affected('xsuaa', 'mta')) {
        relationships.push({
          insert: [xsuaa, 'name'],
          into: [portalDeployer, 'requires', 'name']
        })
      }
      if (affected('ias', 'mta')) {
        relationships.push({
          insert: [ias, 'name'],
          into: [portalDeployer, 'requires', 'name']
        })
      }
      if (affected('html5-repo', 'mta')) {
        relationships.push({
          insert: [html5RepoHost, 'name'],
          into: [portalDeployer, 'requires', 'name']
        })
      }

      if (affected('approuter', 'mta')) {
        relationships.push({
            insert: [portal, 'name'],
            into: [approuter, 'requires', 'name']
        })
      }

      if (affected('multitenancy', 'mta')) {
        relationships.push({
          insert: [portal, 'name'],
          into: [isJava ? srvModule : mtxSidecar4('gen/mtx/sidecar'), 'requires', 'name']
        })
      }

      await merge(__dirname, 'files/mta.yaml.hbs').into('mta.yaml', {
        with: project, additions, relationships
      })
    }

    if (affected('kyma', 'ias')) {
      await merge(__dirname, 'files/values.yaml.hbs').into('chart/values.yaml', { with: project })
      await KymaTemplate.mergeDependency('service-instance', 'portal')
      await renderAndCopy(path.join(__dirname, 'files/portal-site'), path.join(project.html5DeployerPath, 'portal/portal-site'), project)
    }
  }
}
